L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "제 2 불멸체 코어를 기동하는 데 생각보다 시간이 걸려서 말이지."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "第2不滅体コアの起動に思ったより時間がかかってな。"
L24_1.m_Talk_ENG = "It took a bit longer to activate the second Immortal System Core than expected."
L24_1.m_Talk_TWN = "啟動第2個不滅者核心的時候稍微多花了點時間。"
L24_1.m_Talk_THA = "การเปิดใช้งานแกนระบบอิมมอร์ทอลแกนที่ 2 ใช้เวลานานกว่าที่คิดไว้"
L24_1.m_Talk_VTN = "Mất nhiều thời gian để kích hoạt Lõi Hệ Thống Bất Diệt thứ hai hơn dự kiến."
L24_1.m_Talk_SCN = "启动第二个不灭者核心的时候稍微多花了点时间。"
L24_1.m_Talk_DEU = "Es hat länger gedauert, den zweiten Kern der Unsterblichkeitsmatrix zu aktivieren, als gedacht."
L24_1.m_Talk_FRA = "Ça nous a pris plus longtemps que prévu d'activer le second noyau."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP4_ACT4_INTERLUDE_2@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 157
L25_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "QUEEN_REPLACER_NULL_NULL"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "비숍을 중심으로 나와 나이트의 연산능력을 총동원했는데도 조금 전에야 간신히 부트 코드를 작성, 빌드하는 데 성공했다."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "ビショップをメインに、私とナイトの演算能力まで使ったのだ。\nそこまでしてようやくブートコードの作成、ビルドに成功した。"
L25_1.m_Talk_ENG = "Even with the entire computing capacity of Bishop, Knight, and myself, we just barely managed to write and build the booting code."
L25_1.m_Talk_TWN = "就算是以大主教為核心，同時動員我和騎士的總運算能力，也才在不久前編輯好引導代碼。"
L25_1.m_Talk_THA = "แม้จะใช้พลังในการประมวลผลของบิช็อป ไนท์ และตัวฉันรวมกัน ยังลำบากแทบแย่ กว่าจะเขียนโค้ดและสร้างโปรแกรมสำหรับบูตระบบขึ้นมาได้"
L25_1.m_Talk_VTN = "Ngay cả với toàn bộ khả năng tính toán của Quân Tượng, Quân Mã và bản thân ta, chúng ta cũng vô cùng chật vật để viết và xây dựng mã khởi động."
L25_1.m_Talk_SCN = "就算是以大主教为核心，同时动员我和骑士长的运算能力，也只是在不久之前才编辑好引导代码。"
L25_1.m_Talk_DEU = "Selbst mit der gebündelten Rechenleistung von Bishop, Knight und mir konnten wir den Startcode gerade so schreiben."
L25_1.m_Talk_FRA = "Même avec nos capacités de calcul combinées, le fou, le cavalier et moi-même avons à peine réussi à écrire le code de démarrage."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP4_ACT4_INTERLUDE_2@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 157
L26_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L26_1.m_bWaitClick = true
