L26_1.m_CharStrID = "QUEEN_REPLACER_NULL_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "......하지만 조금은 의외였어."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "……しかし、少し意外だった。"
L26_1.m_Talk_ENG = "I must say though, I was a bit surprised."
L26_1.m_Talk_TWN = "……不過我還真有點意外呢。"
L26_1.m_Talk_THA = "แต่ฉันก็ประหลาดใจอยู่พอตัวเลยล่ะ"
L26_1.m_Talk_VTN = "Mặc dù ta phải nói là mình đã ngạc nhiên một chút đấy."
L26_1.m_Talk_SCN = "……但是还有点意外啊。"
L26_1.m_Talk_DEU = "Ich muss gestehen, ich bin überrascht."
L26_1.m_Talk_FRA = "Néanmoins, je suis agréablement surprise."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP4_ACT4_INTERLUDE_2@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 157
L27_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "QUEEN_REPLACER_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "네가 정말로 우리 쪽으로 전향했는지는 좀 의심스러웠는데......"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "お前が本当に私たちの仲間になったのか疑わしかったが……"
L27_1.m_Talk_ENG = "I had my reservations on whether you had truly turned."
L27_1.m_Talk_TWN = "我本來還懷疑妳是不是真的投靠我們了……"
L28_1 = "ตอนแรกก็สงสัยอยู่ ว่าเธอน่ะ คิดจะแปรพรรคมาอยู่กับเราจริงรึเปล่า"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ta đã hơi dè dặt chuyện em đã thực sự quay đầu."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我曾经还怀疑过，你是不是真的投靠我们了……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich hatte meine Zweifel, ob du die Seiten gewechselt hast."
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'avais des doutes quant à ta loyauté."
L27_1.m_Talk_FRA = L28_1
