L28_1.m_Pos = "C"
L29_1 = "이렇게 훌륭하게 임무를 수행해 내다니 말이야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "これほど立派に任務を成し遂げるとは。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "But here you are, having accomplished your mission so well."
L28_1.m_Talk_ENG = L29_1
L29_1 = "沒想到妳這麼完美地完成了任務。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่ในที่สุด เธอก็ทำภารกิจลุล่วงเป็นอย่างดี"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nhưng em đang ở đây, hoàn thành xuất sắc nhiệm vụ của mình."
L28_1.m_Talk_VTN = L29_1
L29_1 = "没想到你这么完美地完成了任务。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Und doch hast du deinen Auftrag sehr gut ausgeführt."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais te voilà, à accomplir ta mission comme on te l'a demandé."
L28_1.m_Talk_FRA = L29_1
