L33_1 = "빈말은 필요없으니까 약속한 거나 잘 지켜."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "お世辞はいいから、それよりも約束はちゃんと守ってよね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Enough with the chitchat. Just remember to keep your promise."
L32_1.m_Talk_ENG = L33_1
L33_1 = "客套話就不用了，妳只要遵守約定就行了。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เรื่องคุยเล่นเอาไว้ทีหลังเถอะค่ะ อย่าลืมสัญญาของคุณด้วยล่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tán gẫu vậy là đủ rồi. Chỉ cần nhớ lấy lời hứa của chị thôi."
L32_1.m_Talk_VTN = L33_1
