L39_1 = "話し中に割り込んで悪いけど、第2不滅体コアって……？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Sorry for butting in... but a second Immortal System Core?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "很抱歉打斷你們，但第2個不滅者核心……？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "โทษทีที่ขัดจังหวะนะ... แต่แกมีแกนระบบอิมมอร์ทอลอันที่ 2 ด้วยเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Xin lỗi vì ngắt lời... nhưng Lõi Hệ Thống Bất Diệt thứ hai ư?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "抱歉打断你们，但是第二个不灭者核心……？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wie war das? Ein zweiter Kern der Unsterblichkeitsmatrix?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je vous coupe, là, mais... Un deuxième noyau ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
