L41_1.m_Pos = "C"
L41_1.m_Crash = 15
L42_1 = "아아, 당신이 델타 세븐의 실비아 레나 쿠퍼로군."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ああ、お前がデルタセブンのシルビア・レナ・クーパーか。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Ah, you must be Sylvia Lena Cooper of Delta Seven."
L41_1.m_Talk_ENG = L42_1
L42_1 = "啊啊，妳是第七三角洲部隊的希爾維亞·蕾娜·庫博啊。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อา เธอคงจะเป็นซิลเวีย เลน่า คูเปอร์ จากเดลต้าเซเว่นสินะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "À, hẳn ngươi là Sylvia Lena Cooper của Delta Seven."
L41_1.m_Talk_VTN = L42_1
L42_1 = "啊啊，你就是德尔塔部队的希尔薇娅啊。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ah, du musst Sylvia Lena Cooper von Delta Seven sein."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oh, vous êtes sûrement Sylvia Lena Cooper de Delta Seven."
L41_1.m_Talk_FRA = L42_1
