L43_1 = "<color=#ffd34c>부사령관</color>님께 이야기는 많이 들었지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "<color=#ffd34c>副司令官</color>から色々話は聞いているぞ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I've heard much about you from the <color=#ffd34c>Deputy Commander</color>."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我經常聽<color=#ffd34c>副司令官</color>提到妳呢。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันได้ยินเรื่องของเธอมามากมายจาก<color=#ffd34c>รองผู้บัญชาการ</color>"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ta đã nghe <color=#ffd34c>Phó Tư Lệnh</color> kể nhiều về ngươi đấy."
L42_1.m_Talk_VTN = L43_1
L43_1 = "经常听<color=#ffd34c>副司令官</color>提起您呢。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Der <color=#ffd34c>stellvertretende Kommandant</color> hat schon viel von dir erzählt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Le <color=#ffd34c>commandant adjoint</color> m'a beaucoup parlé de vous."
L42_1.m_Talk_FRA = L43_1
