L6_1 = "R"
L5_1.m_Pos = L6_1
L6_1 = "불멸체 코어 같은 희귀 유물을 두 개나 가지고 있을 리가 없어!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "不滅体コアのような貴重な遺物を二つも持ってるわけがない！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "There’s no way you’d have more than one rare artifact like the Immortal System Core!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "不滅者核心這麼稀有的遺物，你們怎麼可能會有兩個！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แกจะมีอาร์ติแฟ็กต์หายากอย่างแกนระบบอิมมอร์ทอลมากกว่าหนึ่งชิ้นได้ยังไง!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không đời nào các ngươi có thể tìm được nhiều hơn một di tích như Lõi Hệ Thống Bất Diệt cả!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "不灭者核心这种珍贵的遗物你们怎么可能有两个！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Mehr als ein solch seltenes Artefakt wie den Kern der Unsterblichkeitsmatrix kann niemand besitzen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Aucune chance que vous ayez mis la main sur deux artefacts aussi rares que ce noyau !"
L5_1.m_Talk_FRA = L6_1
