L6_1.m_Crash = L7_1
L7_1 = "어설픈 블러핑 따위가 통할 것 같아?!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そんないい加減なハッタリ、通用すると思う！？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You think your lame attempt at bluffing would work on me?!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "妳以為這種虛張聲勢騙得了我嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "คิดว่าแผนบลัฟโง่ๆ นั่นจะใช้กับฉันได้ผลเหรอ?!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ngươi nghĩ rằng trò lừa đảo nhảm nhí đó sẽ có tác dụng với ta sao?!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "你以为虚张声势就能唬住我吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Glaubst du, ich falle auf so einen billigen Bluff herein?!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu crois vraiment que je vais gober ton baratin ?"
L6_1.m_Talk_FRA = L7_1
