L19_1 = "SHIP_VOICE_BLUE"
L18_1.m_CharStrID = L19_1
L19_1 = "<color=#ffd34c>자세한 상황은 알 수 없지만, 조금 전 에너지 계측기에 말도 안 되는 수치가 찍혔다!</color>"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "<color=#ffd34c>詳しい状況は不明だが、先ほどエネルギー計測器にとんでもない数値が！</color>"
L18_1.m_Talk_JPN = L19_1
