L18_1.m_Talk_ENG = L19_1
L19_1 = "<color=#ffd34c>雖然不知道具體情況，但剛剛能量預測儀上出現了非常誇張的數值！</color>"
L18_1.m_Talk_TWN = L19_1
L19_1 = "<color=#ffd34c>ถึงจะยังยืนยันรายละเอียดไม่ได้ แต่เครื่องสแกนพลังงานแสดงตัวเลขสูงอย่างไม่น่าเชื่อเลย!</color>"
L18_1.m_Talk_THA = L19_1
L19_1 = "<color=#ffd34c>Mặc dù không thể xác nhận chi tiết, nhưng một nhân vật uy lực không thể tin nổi vừa xuất hiện trên máy quét năng lượng!</color>"
L18_1.m_Talk_VTN = L19_1
L19_1 = "<color=#ffd34c>虽然不知道具体情况，但就在刚刚能量探测仪上出现了难以置信的数值！</color>"
L18_1.m_Talk_SCN = L19_1
L19_1 = "<color=#ffd34c>Wir haben zwar noch keine Details, aber die Werte auf dem Energiescanner waren unglaublich hoch!</color>"
L18_1.m_Talk_DEU = L19_1
L19_1 = "<color=#ffd34c>Nous n'avons aucun détail, mais une signature énergétique incroyable vient d'apparaître sur notre radar !</color>"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP4_ACT4_INTERLUDE_2@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 157
L19_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "SHIP_VOICE_BLUE"
L19_1.m_CharStrID = L20_1
L20_1 = "<color=#ffd34c>본 함의 방어 필드로는 그런 출력의 공격을 버티는 게 불가능하다!</color>"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "<color=#ffd34c>本艦の防御フィールドでは、あんな出力の攻撃に耐えられない！</color>"
L19_1.m_Talk_JPN = L20_1
L20_1 = "<color=#ffd34c>This ship’s Force Barrier cannot withstand an attack with that level of output!</color>"
L19_1.m_Talk_ENG = L20_1
L20_1 = "<color=#ffd34c>這艘艦船的原力屏障抵擋不了那樣的攻擊！</color>"
L19_1.m_Talk_TWN = L20_1
L20_1 = "<color=#ffd34c>ฟอร์สบาเรียของยานไม่มีทางต้านทานพลังระดับนั้นได้แน่ๆ!</color>"
L19_1.m_Talk_THA = L20_1
L20_1 = "<color=#ffd34c>Rào Chắn Lực Lượng của con tàu này không thể chịu được một đòn tấn công với mức sát thương đó!</color>"
L19_1.m_Talk_VTN = L20_1
L20_1 = "<color=#ffd34c>这艘舰船的原力屏障抵挡不了那种程度的攻击！</color>"
L19_1.m_Talk_SCN = L20_1
L20_1 = "<color=#ffd34c>Die Energiebarriere dieses Schiffs hat gegen einen Angriff mit einem solchen Ausstoß keine Chance!</color>"
L19_1.m_Talk_DEU = L20_1
L20_1 = "<color=#ffd34c>Notre bouclier ne peut pas résister à une attaque de cette puissance !</color>"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
