L5_1 = "Mọi người còn sống không? Con tàu thế nào rồi?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "还活着吧？！状态怎么样？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Gibt es Verluste? Wie ist euer Zustand?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Tout le monde va bien ? Dans quel état est le vaisseau ?"
L4_1.m_Talk_FRA = L5_1
