L5_1.m_Crash = L6_1
L6_1 = "지, 직격은 피했습니다만...... 피해 상황이 막대합니다!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "直撃は避けましたが……被害状況は甚大です！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "W-we managed to evade a direct hit... But we’ve taken heavy losses!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "雖然避開了直接攻擊……但是損失慘重！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ระ-เราหลบเลี่ยงการปะทะโดยตรงได้... แต่ก็ยังเกิดความสูญเสียมากมายอยู่ดีค่ะ!"
L5_1.m_Talk_THA = L6_1
L6_1 = "C-chúng ta đã tránh được một đòn đánh trực diện... Nhưng cũng phải chịu tổn thất nặng nề!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "虽然避开了正面攻击……但是依然损失惨重！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wir konnten einen Volltreffer vermeiden. A-Aber wir haben schwere Verluste!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "N-Nous avons pu éviter un impact direct, mais..."
L5_1.m_Talk_FRA = L6_1
