L20_1.m_Crash = 25
L21_1 = "말도 안 됩니다. 불멸체 코어는 공격 무기 같은 게 아니에요!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "話になりません。不滅体コアは攻撃武器ではないんです！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "That doesn’t make any sense. The Immortal System Core is not a weapon!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "不可能。不滅者核心不是那種攻擊的武器。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "นี่มันบ้าชัดๆ! แกนระบบอิมมอร์ทอลไม่ใช่อาวุธสักหน่อย!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Điều đó chẳng có ý nghĩa gì cả. Lõi Hệ Thống Bất Diệt không phải là vũ khí!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "不可能。不灭者核心不是那种攻击性的武器。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Das ergibt keinen Sinn. Der Kern der Unsterblichkeitsmatrix ist keine Waffe."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Comment c'est possible ? C'est pas une arme !"
L20_1.m_Talk_FRA = L21_1
