L30_1.m_Pos = "C"
L31_1 = "그쪽 아가씨로부터 클리포트 인자를 손에 넣은 덕분에 가능했지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そちらの娘からクリフォト・ファクターを手に入れられたおかげで可能になった。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "But obtaining the Qliphoth Factor from your girl made this all possible."
L30_1.m_Talk_ENG = L31_1
L31_1 = "但多虧從那位小姐那裡得到了逆卡巴拉因子，我們才能成功的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แต่ด้วยคลิฟอธแฟกเตอร์ที่ได้มาจากเด็กผู้หญิงคนนั้น ทุกอย่างจึงเป็นไปได้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nhưng việc nhận được Thông Số Qliphoth từ cô gái của các ngươi đã khiến mọi việc khả thi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "多亏了从那位小姐那里得到的神圣因子，才成功的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Aber der Klippot-Faktor von eurem Mädchen hat es ermöglicht."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Sans l'agent qliphoth de votre protégée, je ne sais pas si on y serait arrivé."
L30_1.m_Talk_FRA = L31_1
