L37_1 = "거의 무제한의 에너지를 가지고 있는 클리포트 인자 덕분에 제 2......"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ほぼ無制限のエネルギーを持っているクリフォト・ファクターのおかげで、第2……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Thanks to the nearly infinite amount of energy in the Qliphoth Factor..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "多虧了有著近乎無限能量的逆卡巴拉因子，第2……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ด้วยพลังงานที่เกือบจะไร้ขีดจำกัดในคลิฟอธแฟกเตอร์..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Nhờ vào lượng năng lượng gần như vô hạn trong Thông Số Qliphoth..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "多亏了有着无限能量的神圣因子，第二……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Dank der nahezu unerschöpflichen Energie des Klippot-Faktors …"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Grâce à l'énergie quasi infinie produite par l'agent qliphoth..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP4_ACT4_INTERLUDE_2@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 157
L37_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "QUEEN_REPLACER_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "아니, 완성형 불멸체 코어는 더 이상 외부 에너지원을 연결할 필요가 없어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "いや、完成型不滅体コアは、これ以上外部のエネルギー源に繋ぐ必要がないのだ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "The second... I mean, the complete version of the Immortal System Core no longer needs an external energy source."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不，完成型的不滅者核心沒有必要再連接外部能量源了。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ระบบอิมมอร์ทอลรุ่นที่ 2... ไม่สิ รุ่นสมบูรณ์ ก็ไม่จำเป็นต้องใช้แหล่งพลังงานจากภายนอกอีกต่อไป"
L37_1.m_Talk_THA = L38_1
L38_1 = "Lõi thứ hai... Ý ta là, phiên bản hoàn chỉnh của Lõi Hệ Thống Bất Diệt không còn cần nguồn năng lượng đến từ bên ngoài nữa."
L37_1.m_Talk_VTN = L38_1
L38_1 = "不是，完成型不灭者核心没有必要再连接外部能量源。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "… benötigt die zweite – ich meine, die komplette Version des Kerns der Unsterblichkeitsmatrix keine externe Energiequelle mehr."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Le second noyau... Que dis-je ? La version définitive du noyau n'a plus besoin d'une source d'énergie extérieure."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
