L39_1 = "오히려 남는 에너지를 이렇게 외부로 방출할 수 있을 정도지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "むしろ、このように余ったエネルギーを外部に放出できるほどだ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "In fact, it can release the leftover energy like this."
L38_1.m_Talk_ENG = L39_1
L39_1 = "反而還能將剩餘的能量向外部放出。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "และนำพลังงานที่เหลือใช้มายิงเป็นอาวุธแบบนี้ได้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Trên thực tế, nó có thể giải phóng năng lượng còn sót lại như thế này."
L38_1.m_Talk_VTN = L39_1
L39_1 = "反而这种能量可以向外部放出。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Vielmehr kann sie überschüssige Energie auf diese Weise abgeben."
L38_1.m_Talk_DEU = L39_1
L39_1 = "À vrai dire, il peut même expulser l'énergie en surplus, comme vous venez de le voir."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
