L40_1.m_Pos = "C"
L40_1.m_Crash = 20
L41_1 = "방금 그게...... 내 몸에서 추출해 간 클리포트 인자의 에너지라고?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "さっきのそれが……私の体から抽出したクリフォト・ファクターのエネルギーだって？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "That right now... was the energy of the Qliphoth Factor extracted from me?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "剛剛那個……就是從我體內抽出的逆卡巴拉因子能量嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เมื่อกี้... เป็นพลังงานของคลิฟอธแฟกเตอร์ที่ดึงไปจากตัวฉันงั้นรึ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Vậy là ngay lúc này... đó là năng lượng của Thông Số Qliphoth được trích xuất từ ​​tôi sao?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "刚刚那个……是从我体内提取出神圣因子的能量吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Dann war das gerade … die Energie, die der Klippot-Faktor mir entzogen hat?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ça, c'était l'énergie de l'agent qliphoth que vous m'avez prélevé ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
