L43_1 = "UNIT_PRIDE"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "QUEEN_REPLACER_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "하지만 무엇보다 혁신적인 건, 소형화를 통해 불멸체 코어의 이동을 가능하게 했다는 거야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "だが、最も革新的なことは小型化により不滅体コアの移動ができるようになったことだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "The greatest innovation, however, was in the miniaturization of the Core, enabling us to move it around."
L42_1.m_Talk_ENG = L43_1
L43_1 = "但最為革命性的，是把不滅者核心小型化，讓它得以移動。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่นวัตกรรมที่ยอดเยี่ยมที่สุดก็คือการย่อแกนให้มีขนาดเล็ก ทำให้เราพกพาไปที่ไหนก็ได้"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tuy nhiên, bước cải tiến lớn nhất là chính là thu nhỏ Lõi, cho phép bọn ta có thể di chuyển nó đi khắp mọi nơi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "没错。不过最具有创新性的是，我们通过小型化技术，使核心变得可以移动了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Die größte Neuerung war jedoch die Verkleinerung des Kerns, sodass wir ihn jetzt transportieren können."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Cependant, la modification la plus intéressante, c'est d'avoir pu miniaturiser le noyau pour le transporter où on veut."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
