L48_1 = "그래서 이렇게...... 함선에 싣고 움직일 수도 있게 됐지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "だからこのように……艦船に乗せて動かすこともできる。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "And as such... We can now carry it on a ship like this."
L47_1.m_Talk_ENG = L48_1
L48_1 = "所以可以這樣……被艦船載著移動。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ดังนั้น... เราก็เลยพกมันติดยานแบบนี้ได้ด้วย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Và vì vậy... Bây giờ bọn ta có thể để nó trên một con tàu như thế này."
L47_1.m_Talk_VTN = L48_1
L48_1 = "所以可以这样……被舰船载着移动。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Wir können ihn jetzt auf einem solchen Schiff transportieren."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Maintenant, on peut le mettre à bord d'un vaisseau de ce genre."
L47_1.m_Talk_FRA = L48_1
