L33_1 = "안타깝게도 질긴 목숨이 아직 끊어지지 않는군."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "残念ながら、私の命綱はまだ切れないらしい。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Regrettably, my lifeforce has proven to be more tenacious than expected."
L32_1.m_Talk_ENG = L33_1
L33_1 = "真可惜啊，我還沒死呢。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "น่าเสียดาย ที่พลังชีวิตของฉันมันทนทายาดกว่าที่คิดไว้น่ะนะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Thật đáng tiếc, sức sống của ta đã được chứng minh là ngoan cường hơn mong đợi của những người khác."
L32_1.m_Talk_VTN = L33_1
L33_1 = "真可惜啊，我还没死呢。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie sich herausgestellt hat, war mein Überlebenswille bedauerlicherweise größer als gedacht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "À mon grand regret, mes forces vitales se sont montrées bien plus tenaces que je ne l'aurais imaginé."
L32_1.m_Talk_FRA = L33_1
