L44_1 = "当時、単独作戦中だったニューオハイオと共に失踪した、デルタセブン副司令官。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Is the Deputy Commander of Delta Seven who went missing with the New Ohio during a solo operation."
