L44_1 = "是第七三角洲部隊的副司令官，在當時的單獨作戰中和新俄亥俄號一起失蹤了。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "คือรองผู้บัญชาการของเดลต้าเซเว่นที่หายสาบสูญไปกับนิวโอไฮโอในปฏิบัติการเดี่ยว"
L43_1.m_Talk_THA = L44_1
L44_1 = "Là Phó Tư Lệnh của Delta Seven, người đã mất tích cùng với Tân Ohio trong một lần tác chiến cá nhân."
L43_1.m_Talk_VTN = L44_1
L44_1 = "是德尔塔部队的副司令官，在当时的单独作战中和伊欧号一起消失了。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "… ist ein stellvertretender Kommandant der Delta Seven, der während eines Soloeinsatzes mit der New Ohio verschollen ging:"
L43_1.m_Talk_DEU = L44_1
L44_1 = "C'est le commandant adjoint de Delta Seven qui a disparu avec le New Ohio au cours d'une opération en solitaire."
L43_1.m_Talk_FRA = L44_1
