L2_1 = "나도 믿고 싶진 않지만, 저 남자가 여기에 나타났다는 건 아마도......"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "アタシも信じたくはないけど、あの男がここに現れたということは、たぶん……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I wish I could deny it... but if he’s here, that probably means..."
L1_1.m_Talk_ENG = L2_1
L2_1 = "雖然不是很想相信，但那個人會出現在這裡，恐怕……"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันก็ไม่อยากเชื่อหรอกนะ... แต่ในเมื่อเขาอยู่นี่แล้ว ก็หมายความว่า..."
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi ước mình có thể phủ nhận việc này... nhưng nếu ngài ấy ở đây, thì có nghĩa là..."
L1_1.m_Talk_VTN = L2_1
L2_1 = "虽然不想相信，但是如果他在这里出现了，那估计……"
L1_1.m_Talk_SCN = L2_1
L2_1 = "So gern ich es leugnen würde … aber wenn er hier ist, bedeutet das vermutlich …"
L1_1.m_Talk_DEU = L2_1
L2_1 = "J'aimerais avoir tort, mais... S'il est là, ça veut sûrement dire..."
L1_1.m_Talk_FRA = L2_1
