L4_1 = "자네의 총명함이 여전한 것 같아 기쁘군, 실비아."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "シルビア、その相変わらずの聡明さには感心するな。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I’m glad to see you're as sharp as ever, Sylvia."
L3_1.m_Talk_ENG = L4_1
L4_1 = "很高興妳還是這麼聰明，希爾維亞。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันดีใจที่เธอยังฉลาดเหมือนเคยนะ ซิลเวีย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ta rất vui khi thấy cô vẫn sắc sảo như trước đấy, Sylvia."
L3_1.m_Talk_VTN = L4_1
L4_1 = "真高兴啊，你还是这么聪明，希尔薇娅。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Es freut mich, dass du noch so schlau bist wie früher, Sylvia."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je constate que vous êtes toujours aussi vive d'esprit, Sylvia."
L3_1.m_Talk_FRA = L4_1
