L9_1.m_fTalkTime = 0.03
L10_1 = "行方不明になっていた間に、いったいあんたに何があったの？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "What happened to you while you went missing?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "你失蹤的那段時間到底發生了什麼事？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เกิดอะไรขึ้นระหว่างที่คุณหายตัวไปกันแน่?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chuyện gì đã xảy ra với ngài sau khi ngài mất tích vậy?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "你失踪的那段时间到底发生了什么？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Was ist mit dir passiert, während du verschollen warst?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Il vous est arrivé quoi quand vous avez disparu ?"
L9_1.m_Talk_FRA = L10_1
