L10_1.m_Crash = L11_1
L11_1 = "실비아 씨! 관리국으로부터 연락입니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "シルビアさん！　管理局からの連絡です。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Sylvia! We’ve got a transmission from the Administration."
L10_1.m_Talk_ENG = L11_1
L11_1 = "希爾維亞！我收到了管理局的連絡。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ซิลเวีย! เราได้รับสัญญาณติดต่อมาจากองค์การบริหารโลก"
L10_1.m_Talk_THA = L11_1
L11_1 = "Sylvia! Chúng ta vừa nhận được tin từ Cục Quản Lý."
L10_1.m_Talk_VTN = L11_1
L11_1 = "希尔薇娅！管理局那边来电话了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Sylvia! Wir empfangen einen Funkspruch von der Administration."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Sylvia ! J'ai reçu une transmission de l'Administration."
L10_1.m_Talk_FRA = L11_1
