L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "정지했던 로스트 쉽들이...... 다시 재생되기 시작했다고 합니다!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "停止していたロストシップが……また再生を始めたそうです！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "They're saying the Lost Ships... are regenerating again!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "靜止的失落艦船……又開始再生了。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "พวกเขาบอกว่ายานที่สาบสูญ... เริ่มฟื้นสภาพกลับมาอีกแล้ว!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Những Chiến Hạm Mất Tích... đang phục hồi trở lại!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "失落舰船……又开始再生了。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sie sagen, die Verlorenen Schiffe … regenerieren sich wieder!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Les vaisseaux perdus... Ils ont recommencé à se régénérer !"
L11_1.m_Talk_FRA = L12_1
