L12_1.m_Pos = L13_1
L13_1 = "줄어들던 이상침식지대도 확장되고 있습니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "縮小していた異常侵食地帯も再び広がっています。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "The diminishing Corrupted Areas are expanding as well..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "縮小的異常侵蝕地區又擴大了。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "พื้นที่ที่ถูกคอร์รัปต์ก็กลับมาขยายอาณาเขตด้วยเหมือนกัน..."
L12_1.m_Talk_THA = L13_1
L13_1 = "Các Khu Vực Bị Ăn Mòn đang dần biến mất cũng được mở rộng..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "缩小的异常侵蚀地区又扩大了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Auch die schrumpfenden verderbten Gebiete wachsen wieder …"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Et les zones corrompues à regagner du terrain aussi..."
L12_1.m_Talk_FRA = L13_1
