L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 157
L22_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
