L23_1 = "KING_REPLACER_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "m_bCharHologramEffect"
L22_1[L23_1] = true
L23_1 = "오랜만에 만나서 반가웠네. 카일, 실비아."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "久しぶりに会えて嬉しかったよ。カイル、シルビア。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "It was a pleasure seeing you again. Kyle, Sylvia."
L22_1.m_Talk_ENG = L23_1
L23_1 = "很高興我們久違重逢！凱爾，希爾維亞。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ดีใจที่ได้เจอพวกเธออีกครั้งนะ ไคล์ ซิลเวีย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Rất vui khi gặp lại các cậu. Kyle, Sylvia."
L22_1.m_Talk_VTN = L23_1
L23_1 = "很高兴能再见到你们，凯尔，希尔薇娅。我本来是想这么说的。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Hat mich gefreut, euch wiederzusehen. Kyle, Sylvia."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Kyle, Sylvia. Ce fut un plaisir de vous revoir."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP4_ACT4_INTERLUDE_2@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 157
L23_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "KING_REPLACER_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "하지만 재회의 기쁨을 나누기엔 시간이 부족하군."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "でも、再会の喜びを分かち合うには時間が足りないな。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But unfortunately, we do not have enough time to indulge in this reunion."
L23_1.m_Talk_ENG = L24_1
L24_1 = "但我們沒有時間享受重逢的喜悅了呢。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่น่าเสียดาย ที่เราไม่มีเวลามาปลาบปลื้มกับการพบกันครั้งนี้แล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nhưng tiếc thay, chúng ta không có đủ thời gian để tận hưởng buổi hội ngộ này."
L23_1.m_Talk_VTN = L24_1
L24_1 = "但是好像没有时间享受重逢的喜悦了呢。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Leider haben wir nicht die Zeit, unser Stelldichein auszukosten."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Malheureusement, nous n'avons pas le temps de nous éterniser dans ces retrouvailles."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
