L27_1 = "พูดอะไรของคุณน่ะ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ngài đang nói cái gì vậy?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "说什么啊？！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Was redest du da?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Comment ça ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP4_ACT4_INTERLUDE_2@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 157
L27_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L28_1 = "R"
L27_1.m_Pos = L28_1
L28_1 = "이렇게 갑자기 나타났다가, 또 멋대로 사라진다고?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "こんなに突然現れておいて、また勝手に消えるというの？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You think you can just pop out of nowhere and vanish again?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "就這樣讓你突然出現，然後擅自消失？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อยู่ๆ ก็โผล่มาจากไหนไม่รู้ แล้วนี่จะหายตัวไปอีก"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ngài nghĩ mình có thể nhảy ra từ đâu đó rồi biến mất một lần nữa sao?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "这么突然地出现就又要走了吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Glaubst du, wir lassen dich jetzt einfach wieder abhauen?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Vous croyez que vous pouvez vous pointer comme une fleur et repartir comme ça ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP4_ACT4_INTERLUDE_2@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 157
L28_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "SYLVIA_DELTA_NULL_NULL"
L29_1 = "R"
L28_1.m_Pos = L29_1
L28_1.m_Crash = 60
L29_1 = "우리가 그렇게 우스워 보여?!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "アタシたちのこと、舐めてる！？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Do you really think that little of us?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "我們有那麼可笑嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "สำหรับคุณ พวกเรามีความสำคัญแค่นี้เองน่ะเหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ngài thực sự không coi chúng tôi ra gì hết đấy à?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "我们有那么可笑吗？！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Hältst du wirklich so wenig von uns?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "C'est tout ce qu'on vaut, à vos yeux ?"
L28_1.m_Talk_FRA = L29_1
