L31_1 = "EP4_ACT4_INTERLUDE_2@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 157
L30_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "KING_REPLACER_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "m_bCharHologramEffect"
L30_1[L31_1] = true
L31_1 = "지금은 이해하지 못하겠지만, 난 자네들과 무익한 싸움을 할 생각이 전혀 없네."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "今は理解できないだろうが、私は君たちと無益な戦いをするつもりはないんだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You may not understand me now, but I have no intent of engaging in an unproductive battle with you."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你們現在可能無法理解，我一點也不想和你們進行沒有利益的戰鬥。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เธออาจจะยังไม่เข้าใจฉัน แต่ในตอนนี้ ฉันไม่ต้องการที่จะต่อสู้อย่างเปล่าประโยชน์กับเธอ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Bây giờ các cậu sẽ không thể hiểu được ta, nhưng ta không có ý định tham gia vào một cuộc chiến không có kết quả với các cậu."
L30_1.m_Talk_VTN = L31_1
L31_1 = "你们现在可能不太理解，我一点也不想和你们进行无意义的战斗。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ihr mögt es jetzt noch nicht verstehen, aber ich habe kein Interesse an einem sinnlosen Kampf mit euch."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Vous ne me comprenez peut-être pas pour le moment, mais je n'ai nulle intention de me lancer dans un affrontement inutile avec vous."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP4_ACT4_INTERLUDE_2@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 157
L31_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "KING_REPLACER_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "우린 이대로 제 2 불멸체 코어와 함께 차원의 틈으로 사라질 예정이지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "我々はこのまま第2不滅体コアと共に次元の狭間に消える予定だ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "We will vanish into the the interdimensional gap along with the second Immortal System Core."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我們預定和第2個不滅者核心一起消失在次元縫隙中。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "พวกเราจะหายตัวไปในช่องว่างระหว่างมิติ พร้อมกับแกนระบบอิมมอร์ทอลแกนที่ 2"
L31_1.m_Talk_THA = L32_1
L32_1 = "Bọn ta sẽ biến vào khoảng trống liên không gian cùng với Lõi Hệ Thống Bất Diệt thứ hai."
L31_1.m_Talk_VTN = L32_1
L32_1 = "按照原定计划，我们会和第二个不灭者核心一起进入次元缝中。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Wir verschwinden zusammen mit dem zweiten Kern der Unsterblichkeitsmatrix durch den interdimensionalen Spalt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Nous allons disparaître avec le second noyau dans l'espace entre les dimensions."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
