L36_1 = "EP4_ACT4_INTERLUDE_2@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 157
L35_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L35_1.m_bWaitClick = true
