L36_1 = "KYLE_DELTA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "L"
L35_1.m_Pos = L36_1
L36_1 = 50
L35_1.m_Crash = L36_1
L36_1 = "이런! 막아야 합니다!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それはマズい！　阻止せねば！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Dang it! We have to stop them!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "可惡！阻止他！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แย่ล่ะ! เราต้องหยุดพวกเขา!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chết tiệt! Chúng ta phải ngăn chúng lại!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "可恶！快阻止他！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Verdammt! Wir müssen sie aufhalten!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Bon sang ! On doit les arrêter !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP4_ACT4_INTERLUDE_2@236#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 236
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 157
L36_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "KYLE_DELTA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "L"
L36_1.m_Pos = L37_1
L37_1 = "뉴 오하이오는 원래 차원간 은닉 잠항 기술을 특화시켜 제작한 스텔스 함선입니다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ニューオハイオはもともと、次元間隠匿潜航技術に特化して製作したステルス艦船です。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "The New Ohio was designed for clandestine interdimensional navigation."
L36_1.m_Talk_ENG = L37_1
L37_1 = "新俄亥俄號是特化了原本的次元間隱匿潛航技術，所建造出來的隱形艦船。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นิวโอไฮโอออกแบบมาเพื่อทำปฏิบัติการลับในพื้นที่ระหว่างมิติ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tân Ohio được thiết kế để điều hướng liên không gian trong bí mật."
L36_1.m_Talk_VTN = L37_1
L37_1 = "伊欧号是应用了隐匿潜航技术的隐形舰船。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Die New Ohio wurde für geheime Navigation zwischen den Dimensionen konzipiert."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Le New Ohio a été conçu pour la navigation clandestine entre les dimensions."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP4_ACT4_INTERLUDE_2@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 157
L37_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "KYLE_DELTA_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "L"
L37_1.m_Pos = L38_1
L38_1 = 30
L37_1.m_Crash = L38_1
L38_1 = "한 번 차원의 틈으로 빠져 버리면 현재 기술로는 추적할 방법이 없습니다!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "一度次元の狭間に行ってしまったら、現在の技術では追跡する術がありません！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "We don’t have the technology to track a stealth craft like that once it enters the interdimensional gap."
L37_1.m_Talk_ENG = L38_1
L38_1 = "一旦逃脫到了次元縫隙中，以現在的技術是無法追蹤的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เราไม่มีเทคโนโลยีที่จะติดตามยานล่องหนแบบนั้น ถ้ามันเข้าไปในช่องระหว่างมิติแล้ว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chúng ta không có công nghệ để theo dõi một chiếc chiến hạm tàng hình như vậy một khi nó đi vào khoảng trống liên không gian."
L37_1.m_Talk_VTN = L38_1
L38_1 = "一旦进入次元缝中，就无法以现有技术追踪到了。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sobald sie den interdimensionalen Spalt erreicht, können wir sie nicht mehr aufspüren."
L37_1.m_Talk_DEU = L38_1
L38_1 = "On ne dispose pas de la technologie nécessaire pour pister un vaisseau furtif comme celui-là une fois qu'il se trouve dans la zone interdimensionnelle."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
