L40_1 = "EP4_ACT4_INTERLUDE_2@239#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 157
L39_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "KING_REPLACER_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "m_bCharHologramEffect"
L39_1[L40_1] = true
L40_1 = "이대로 우리가 사라지고 나면 테라사이드 프로젝트를 방해할 자는 아무도 없겠지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "このまま私たちがいなくなれば、テラサイドプロジェクトを妨害されることもなかろう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Once we vanish, no one will be able to interfere with the Project Terraside from now on."
L39_1.m_Talk_ENG = L40_1
L40_1 = "如果我們就這樣消失的話，就沒有人能阻止特拉賽德計畫了吧。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เมื่อเราหายตัวไป ก็จะไม่ใครขัดขวางโปรเจ็กต์เทอร์ราไซด์ได้อีกนับจากนี้"
L39_1.m_Talk_THA = L40_1
L40_1 = "Một khi chúng ta biến mất, kể từ bây giờ sẽ không ai có thể can thiệp vào Dự Án Terraside được nữa."
L39_1.m_Talk_VTN = L40_1
L40_1 = "没错，一旦我们进入了次元缝中，就没有人能够阻止特拉赛德计划了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sobald wir verschwunden sind, kann niemand mehr das Terraside-Projekt verhindern."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Quand nous aurons disparu, plus personne ne pourra entraver l'exécution du projet Terremonde."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP4_ACT4_INTERLUDE_2@240#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 240
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 157
L40_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "KING_REPLACER_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "자네들도, 아니, 그 누구라도."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "君たち、いや、他の誰からもな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Not you or anyone else."
L40_1.m_Talk_ENG = L41_1
L41_1 = "包括你們，不，是任何人。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไม่ว่าจะเป็นพวกเธอ หรือใครก็ตาม"
L40_1.m_Talk_THA = L41_1
L41_1 = "Không một ai, dù là các cậu hoặc là những người khác."
L40_1.m_Talk_VTN = L41_1
L41_1 = "包括你们，不，是任何人。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ihr nicht und auch sonst niemand."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Vous y compris."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP4_ACT4_INTERLUDE_2@241#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 241
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 157
L41_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "KING_REPLACER_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "그럼 잘 있게. 카일, 실비아."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "じゃあ、元気でな。カイル、シルビア。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "So long, then. Kyle, Sylvia."
L41_1.m_Talk_ENG = L42_1
L42_1 = "那就保重吧。凱爾，希爾維亞。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ฉันคงต้องขอตัวก่อน ไคล์ ซิลเวีย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đã lâu rồi. Kyle, Sylvia."
L41_1.m_Talk_VTN = L42_1
L42_1 = "你们就好好呆着吧。凯尔，希尔薇娅。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Auf bald. Kyle, Sylvia."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Alors, au revoir. Kyle, Sylvia."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP4_ACT4_INTERLUDE_2@242#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 242
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 157
L42_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "KING_REPLACER_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "짧은 만남이었지만, 진심으로 반가웠네."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "短い再会だったが、会えて本当に嬉しかったよ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "As brief as it was, I enjoyed our little reunion."
L42_1.m_Talk_ENG = L43_1
L43_1 = "雖然時間很短，但我真的很高興再見到你們。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถึงจะเป็นช่วงเวลาครู่เดียว แต่ฉันก็ดีใจที่ได้เจอพวกเธออีก"
L42_1.m_Talk_THA = L43_1
L43_1 = "Dù ngắn ngủi nhưng ta rất thích buổi hội ngộ nho nhỏ này."
L42_1.m_Talk_VTN = L43_1
L43_1 = "虽然时间很短，但我真的很高兴见到你们。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich habe unser kurzes Wiedersehen sehr genossen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "J'ai apprécié ces très brèves retrouvailles."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP4_ACT4_INTERLUDE_2@243#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 243
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 157
L43_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "KING_REPLACER_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "테라사이드 작전이 종료되고, 지구의 모든 <color=#ffd34c>적합한</color> 인류가 리플레이서로 바뀌었을 때."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "テラサイド作戦が終了し、地球上のすべての<color=#ffd34c>選ばれた</color>人類がリプレイサーになった時、"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Once the Terraside operation is complete and when all <color=#ffd34c>appropriate</color> humanity have been transformed into Replacers..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "等到特拉賽德作戰結束，地球上所有<color=#ffd34c>合適的</color> 人類都變成了克隆體後。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เมื่อปฏิบัติการเทอร์ราไซด์เสร็จสมบูรณ์ และมนุษยชาติที่<color=#ffd34c>คู่ควร</color>ทุกคนได้เป็นรีเพลสเซอร์..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Khi chiến dịch Terraside hoàn tất và khi tất cả nhân loại <color=#ffd34c>thích hợp</color> đã được chuyển thành Người Nhân Bản..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "等到特拉赛德作战结束，地球上所有的<color=#ffd34c>合适的</color> 人都变成了克隆集团的一员之后。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Sobald die Terraside-Operation abgeschlossen ist und alle <color=#ffd34c>passenden</color> Menschen in Replacer verwandelt wurden …"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Lorsque l'opération Terremonde sera achevée et que tous les humains <color=#ffd34c>adéquats</color> auront été transformés en substituts..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP4_ACT4_INTERLUDE_2@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 157
L44_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "KING_REPLACER_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "그때 다시 만나도록 하지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "その時にまた会うとしよう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I’ll see you again then."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我們就在那個時候再見吧。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันจะกลับมาอีก"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ta sẽ gặp lại các cậu."
L44_1.m_Talk_VTN = L45_1
L45_1 = "到那个时候我们再见吧。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "… sehen wir uns wieder."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Nous nous reverrons."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP4_ACT4_INTERLUDE_2@245#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 245
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 157
L45_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "KING_REPLACER_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "그동안 중장님께도 안부 전해 주면 좋겠군."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "中将にもよろしく伝えてくれ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Please send the Lieutenant General my regards."
L45_1.m_Talk_ENG = L46_1
L46_1 = "這段時間幫我向中將問好。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฝากทักทายพลโทให้ฉันด้วยล่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hãy thay ta gửi đến Trung Tướng lời chào trân trọng nhé."
L45_1.m_Talk_VTN = L46_1
L46_1 = "这段时间请帮我向中将问好。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Bitte grüßt den Generalleutnant von mir."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Transmettez mes respects les plus sincères à la lieutenante générale."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP4_ACT4_INTERLUDE_2@246#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 246
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 157
L46_1.m_CutScenStrID = "EP4_ACT4_INTERLUDE_2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "KING_REPLACER_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "그럼 이만."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "それではな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Bye now."
L46_1.m_Talk_ENG = L47_1
L47_1 = "那就告辭了。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ลาก่อน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Giờ thì tạm biệt."
L46_1.m_Talk_VTN = L47_1
L47_1 = "那么，就这样。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Bis bald."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Au revoir."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
