L49_1 = 50
L48_1.m_Crash = L49_1
L49_1 = "잠깐! 멈춰! 멈추라고!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ちょっと待って！　待ってよ！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Wait! Stop! I said, stop!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "等一下！停下來！你給我停下來！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เดี๋ยวก่อน! หยุดนะ! บอกให้หยุดไงล่ะ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Khoan! Dừng lại! Tôi nói là dừng lại!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "等等！停下来！你给我停下来！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Warte! Halt! Ich sagte halt!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Attendez ! Arrêtez-vous ! Vous m'entendez ?"
L48_1.m_Talk_FRA = L49_1
